INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001401', '50000000-0000-0000-0000-000000000049', 'simple', 'mcq', 'What is supervised learning?', '["Learning from labeled data", "Learning from unlabeled data", "Learning from rewards", "Learning without data"]', 'Learning from labeled data', 'Supervised learning uses labeled training data where each example has input features and corresponding output labels.', 'active'),
('60000000-0000-0000-0000-000000001402', '50000000-0000-0000-0000-000000000049', 'simple', 'mcq', 'Which of these is a supervised learning task?', '["Classification", "Clustering", "Dimensionality reduction", "Association"]', 'Classification', 'Classification predicts discrete class labels and is a supervised learning task.', 'active'),
('60000000-0000-0000-0000-000000001403', '50000000-0000-0000-0000-000000000049', 'simple', 'mcq', 'What is regression in machine learning?', '["Predicting continuous values", "Predicting categories", "Grouping similar data", "Reducing features"]', 'Predicting continuous values', 'Regression predicts continuous numerical values, such as house prices or temperature.', 'active'),
('60000000-0000-0000-0000-000000001404', '50000000-0000-0000-0000-000000000049', 'simple', 'mcq', 'What is the target variable in supervised learning?', '["The output we want to predict", "The input features", "The training algorithm", "The evaluation metric"]', 'The output we want to predict', 'The target variable (also called dependent variable) is what the model learns to predict from input features.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001405', '50000000-0000-0000-0000-000000000049', 'intermediate', 'mcq', 'What is overfitting in machine learning?', '["Model performs well on training data but poorly on unseen data", "Model performs poorly on both training and test data", "Model is too simple", "Model has high bias"]', 'Model performs well on training data but poorly on unseen data', 'Overfitting occurs when a model learns the training data too well, including noise, and fails to generalize.', 'active'),
('60000000-0000-0000-0000-000000001406', '50000000-0000-0000-0000-000000000049', 'intermediate', 'mcq', 'What is the bias-variance tradeoff?', '["Tradeoff between model complexity and generalization", "Tradeoff between speed and accuracy", "Tradeoff between memory and computation", "Tradeoff between features and samples"]', 'Tradeoff between model complexity and generalization', 'Simple models have high bias (underfit), complex models have high variance (overfit). The tradeoff balances these.', 'active'),
('60000000-0000-0000-0000-000000001407', '50000000-0000-0000-0000-000000000049', 'intermediate', 'mcq', 'What is cross-validation used for?', '["Estimating model performance on unseen data", "Training the final model", "Selecting features", "Reducing dimensionality"]', 'Estimating model performance on unseen data', 'Cross-validation splits data into multiple folds to get a better estimate of how the model will perform on new data.', 'active'),
('60000000-0000-0000-0000-000000001408', '50000000-0000-0000-0000-000000000049', 'intermediate', 'code_mcq', 'Which sklearn function splits data into train and test sets?', '["train_test_split()", "split_data()", "data_split()", "divide_dataset()"]', 'train_test_split()', 'sklearn.model_selection.train_test_split() randomly splits arrays or matrices into train and test subsets.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001409', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'What is the No Free Lunch theorem?', '["No single algorithm works best for all problems", "All algorithms are equally good", "Algorithms should be free", "Training should be costless"]', 'No single algorithm works best for all problems', 'The No Free Lunch theorem states that no algorithm outperforms all others across all possible problems.', 'active'),
('60000000-0000-0000-0000-000000001410', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'What is the difference between L1 and L2 regularization?', '["L1 can produce sparse models, L2 shrinks coefficients", "L2 is for classification, L1 for regression", "L1 is faster, L2 is more accurate", "No difference"]', 'L1 can produce sparse models, L2 shrinks coefficients', 'L1 regularization (Lasso) can zero out coefficients, L2 (Ridge) shrinks them toward zero but not exactly to zero.', 'active'),
('60000000-0000-0000-0000-000000001411', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'What is the VC dimension?', '["Measure of model complexity/capacity", "Validation accuracy", "Training time", "Number of parameters"]', 'Measure of model complexity/capacity', 'VC dimension measures the capacity of a model to shatter points - higher VC dimension means more complex models.', 'active'),
('60000000-0000-0000-0000-000000001412', '50000000-0000-0000-0000-000000000049', 'expert', 'code_mcq', 'Which sklearn class implements logistic regression?', '["LogisticRegression", "LinearRegression", "LogitRegression", "ClassifierLR"]', 'LogisticRegression', 'sklearn.linear_model.LogisticRegression implements logistic regression for classification tasks.', 'active'),
('60000000-0000-0000-0000-000000001413', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'What is the maximum depth of a decision tree with n samples?', '["n-1", "log2(n)", "sqrt(n)", "n"]', 'n-1', 'In the worst case, a decision tree can have depth n-1, creating a leaf for each sample (overfitting).', 'active');
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001414', '50000000-0000-0000-0000-000000000050', 'simple', 'mcq', 'What is unsupervised learning?', '["Learning from unlabeled data", "Learning from labeled data", "Learning from rewards", "Learning with teacher"]', 'Learning from unlabeled data', 'Unsupervised learning finds patterns in data without predefined labels or target variables.', 'active'),
('60000000-0000-0000-0000-000000001415', '50000000-0000-0000-0000-000000000050', 'simple', 'mcq', 'What is clustering?', '["Grouping similar data points", "Predicting categories", "Reducing features", "Finding associations"]', 'Grouping similar data points', 'Clustering groups data points based on similarity without using predefined labels.', 'active'),
('60000000-0000-0000-0000-000000001416', '50000000-0000-0000-0000-000000000050', 'simple', 'mcq', 'What is dimensionality reduction?', '["Reducing number of features", "Increasing number of samples", "Adding more labels", "Creating more clusters"]', 'Reducing number of features', 'Dimensionality reduction reduces the number of input features while preserving important information.', 'active'),
('60000000-0000-0000-0000-000000001417', '50000000-0000-0000-0000-000000000050', 'simple', 'mcq', 'Which algorithm is commonly used for clustering?', '["K-Means", "Linear Regression", "SVM", "Decision Tree"]', 'K-Means', 'K-Means is a popular clustering algorithm that partitions data into K clusters based on similarity.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001418', '50000000-0000-0000-0000-000000000050', 'intermediate', 'mcq', 'What is the elbow method used for?', '["Determining optimal number of clusters", "Measuring accuracy", "Selecting features", "Regularizing models"]', 'Determining optimal number of clusters', 'The elbow method plots inertia against number of clusters; the "elbow" point suggests optimal K.', 'active'),
('60000000-0000-0000-0000-000000001419', '50000000-0000-0000-0000-000000000050', 'intermediate', 'mcq', 'What is PCA?', '["Principal Component Analysis for dimensionality reduction", "Principal Classification Algorithm", "Primary Component Aggregation", "Pattern Correlation Analysis"]', 'Principal Component Analysis for dimensionality reduction', 'PCA transforms data to new coordinate system where greatest variance lies on first component, second greatest on second, etc.', 'active'),
('60000000-0000-0000-0000-000000001420', '50000000-0000-0000-0000-000000000050', 'intermediate', 'mcq', 'What is anomaly detection?', '["Identifying rare or unusual data points", "Classifying normal data", "Clustering similar data", "Predicting trends"]', 'Identifying rare or unusual data points', 'Anomaly detection identifies data points that deviate significantly from the majority of the data.', 'active'),
('60000000-0000-0000-0000-000000001421', '50000000-0000-0000-0000-000000000050', 'intermediate', 'code_mcq', 'Which sklearn function implements K-Means clustering?', '["KMeans()", "ClusterKMeans()", "KMeansClustering()", "KMeansCluster()"]', 'KMeans()', 'sklearn.cluster.KMeans() implements the K-Means clustering algorithm.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001422', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'What is the difference between PCA and t-SNE?', '["PCA is linear, t-SNE is nonlinear", "t-SNE is faster", "PCA preserves global structure", "No difference"]', 'PCA is linear, t-SNE is nonlinear', 'PCA performs linear dimensionality reduction, while t-SNE is nonlinear and better for visualization.', 'active'),
('60000000-0000-0000-0000-000000001423', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'What is DBSCAN?', '["Density-based clustering algorithm", "Distance-based classification", "Decision boundary algorithm", "Database scanning"]', 'Density-based clustering algorithm', 'DBSCAN groups points that are closely packed together, marking outliers in low-density regions.', 'active'),
('60000000-0000-0000-0000-000000001424', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'What is the curse of dimensionality?', '["Problems when number of features is high", "Too many samples", "Too few clusters", "Overfitting in low dimensions"]', 'Problems when number of features is high', 'High-dimensional spaces make distance metrics less meaningful and require exponentially more data.', 'active'),
('60000000-0000-0000-0000-000000001425', '50000000-0000-0000-0000-000000000050', 'expert', 'code_mcq', 'Which sklearn class implements PCA?', '["PCA()", "PrincipalComponentAnalysis()", "DimReducePCA()", "PCATransform()"]', 'PCA()', 'sklearn.decomposition.PCA() implements Principal Component Analysis.', 'active'),
('60000000-0000-0000-0000-000000001426', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'What is the time complexity of K-Means?', '["O(n * K * I * d)", "O(n^2)", "O(n log n)", "O(K^3)"]', 'O(n * K * I * d)', 'K-Means complexity is O(n * K * I * d) where n=samples, K=clusters, I=iterations, d=dimensions.', 'active');
INSERT INTO subjects (id, domain_id, name, status) 
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001427', '50000000-0000-0000-0000-000000000051', 'simple', 'mcq', 'What is an artificial neuron?', '["Mathematical model inspired by biological neurons", "Computer processor", "Memory cell", "Logic gate"]', 'Mathematical model inspired by biological neurons', 'Artificial neurons receive inputs, apply weights and bias, then pass through activation function to produce output.', 'active'),
('60000000-0000-0000-0000-000000001428', '50000000-0000-0000-0000-000000000051', 'simple', 'mcq', 'What is an activation function?', '["Function that determines neuron output", "Function that initializes weights", "Function that computes loss", "Function that optimizes parameters"]', 'Function that determines neuron output', 'Activation functions introduce non-linearity, allowing neural networks to learn complex patterns.', 'active'),
('60000000-0000-0000-0000-000000001429', '50000000-0000-0000-0000-000000000051', 'simple', 'mcq', 'What is a perceptron?', '["Single-layer neural network", "Multi-layer network", "Recurrent network", "Convolutional network"]', 'Single-layer neural network', 'A perceptron is the simplest neural network with input layer directly connected to output layer.', 'active'),
('60000000-0000-0000-0000-000000001430', '50000000-0000-0000-0000-000000000051', 'simple', 'mcq', 'Which activation function outputs between 0 and 1?', '["Sigmoid", "ReLU", "Tanh", "Linear"]', 'Sigmoid', 'Sigmoid function outputs values between 0 and 1, useful for probability outputs.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001431', '50000000-0000-0000-0000-000000000051', 'intermediate', 'mcq', 'What is backpropagation?', '["Algorithm for training neural networks by computing gradients", "Forward pass through network", "Weight initialization method", "Activation function"]', 'Algorithm for training neural networks by computing gradients', 'Backpropagation computes gradients of loss with respect to weights using chain rule, then updates weights.', 'active'),
('60000000-0000-0000-0000-000000001432', '50000000-0000-0000-0000-000000000051', 'intermediate', 'mcq', 'What is the vanishing gradient problem?', '["Gradients become extremely small during backpropagation", "Gradients become too large", "No gradients are computed", "Gradients oscillate"]', 'Gradients become extremely small during backpropagation', 'In deep networks, gradients can become vanishingly small, preventing weights in early layers from updating.', 'active'),
('60000000-0000-0000-0000-000000001433', '50000000-0000-0000-0000-000000000051', 'intermediate', 'mcq', 'What is dropout?', '["Regularization technique that randomly drops neurons during training", "Weight initialization method", "Activation function", "Optimization algorithm"]', 'Regularization technique that randomly drops neurons during training', 'Dropout prevents overfitting by randomly disabling neurons during training, forcing network to learn robust features.', 'active'),
('60000000-0000-0000-0000-000000001434', '50000000-0000-0000-0000-000000000051', 'intermediate', 'code_mcq', 'Which TensorFlow function creates a dense layer?', '["tf.keras.layers.Dense()", "tf.layers.dense()", "tf.nn.dense()", "tf.DenseLayer()"]', 'tf.keras.layers.Dense()', 'tf.keras.layers.Dense() creates a fully connected neural network layer.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001435', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'What is Xavier/Glorot initialization?', '["Weight initialization method for sigmoid/tanh", "Activation function", "Optimization algorithm", "Regularization technique"]', 'Weight initialization method for sigmoid/tanh', 'Xavier initialization sets weights with variance 1/n_inputs, helping prevent vanishing/exploding gradients for sigmoid/tanh.', 'active'),
('60000000-0000-0000-0000-000000001436', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'What is batch normalization?', '["Normalizing layer inputs to reduce internal covariate shift", "Normalizing dataset before training", "Batch processing of data", "Normalizing weights"]', 'Normalizing layer inputs to reduce internal covariate shift', 'Batch normalization normalizes the outputs of a layer to have zero mean and unit variance, improving training stability.', 'active'),
('60000000-0000-0000-0000-000000001437', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'What is the difference between Adam and SGD optimizers?', '["Adam uses adaptive learning rates, SGD uses fixed", "SGD is always better", "Adam doesn''t use gradients", "No difference"]', 'Adam uses adaptive learning rates, SGD uses fixed', 'Adam combines ideas from RMSprop and momentum with adaptive learning rates for each parameter.', 'active'),
('60000000-0000-0000-0000-000000001438', '50000000-0000-0000-0000-000000000051', 'expert', 'code_mcq', 'Which PyTorch class defines a neural network module?', '["nn.Module", "nn.Network", "torch.Module", "torch.Network"]', 'nn.Module', 'In PyTorch, nn.Module is the base class for all neural network modules.', 'active'),
('60000000-0000-0000-0000-000000001439', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'What is the universal approximation theorem?', '["Neural network can approximate any continuous function", "All networks converge", "Training always succeeds", "No network can learn everything"]', 'Neural network can approximate any continuous function', 'A feedforward network with single hidden layer and enough neurons can approximate any continuous function.', 'active');
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001440', '50000000-0000-0000-0000-000000000052', 'simple', 'mcq', 'What is a CNN used for?', '["Image processing and computer vision", "Time series prediction", "Text generation", "Recommendation systems"]', 'Image processing and computer vision', 'Convolutional Neural Networks use convolutional layers to detect spatial patterns, ideal for images.', 'active'),
('60000000-0000-0000-0000-000000001441', '50000000-0000-0000-0000-000000000052', 'simple', 'mcq', 'What is an RNN used for?', '["Sequential data like text or time series", "Image classification", "Tabular data", "Audio classification"]', 'Sequential data like text or time series', 'Recurrent Neural Networks have memory to process sequences, making them suitable for time-series and text.', 'active'),
('60000000-0000-0000-0000-000000001442', '50000000-0000-0000-0000-000000000052', 'simple', 'mcq', 'What is a transformer architecture?', '["Self-attention based architecture for sequences", "Image segmentation network", "Clustering algorithm", "Dimensionality reduction"]', 'Self-attention based architecture for sequences', 'Transformers use self-attention mechanisms and have become standard for NLP tasks like translation and GPT models.', 'active'),
('60000000-0000-0000-0000-000000001443', '50000000-0000-0000-0000-000000000052', 'simple', 'mcq', 'What is transfer learning?', '["Using pre-trained model for new task", "Transferring data between servers", "Moving model to different hardware", "Converting model format"]', 'Using pre-trained model for new task', 'Transfer learning leverages knowledge from pre-trained models on large datasets for new, related tasks.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001444', '50000000-0000-0000-0000-000000000052', 'intermediate', 'mcq', 'What is attention mechanism?', '["Focusing on relevant parts of input", "Memory unit in RNN", "Activation function", "Regularization technique"]', 'Focusing on relevant parts of input', 'Attention allows models to focus on specific parts of input sequence when producing output, improving performance on long sequences.', 'active'),
('60000000-0000-0000-0000-000000001445', '50000000-0000-0000-0000-000000000052', 'intermediate', 'mcq', 'What is LSTM?', '["Long Short-Term Memory network for sequences", "Lightweight Sequential Transfer Model", "Linear Statistical Time Model", "Layer-wise Stochastic Training Method"]', 'Long Short-Term Memory network for sequences', 'LSTM is a type of RNN with gating mechanisms to remember long-term dependencies and avoid vanishing gradients.', 'active'),
('60000000-0000-0000-0000-000000001446', '50000000-0000-0000-0000-000000000052', 'intermediate', 'mcq', 'What is a GAN?', '["Generative Adversarial Network", "Gradient Accumulation Network", "Generalized Activation Network", "Grouped Attention Network"]', 'Generative Adversarial Network', 'GANs consist of generator and discriminator networks competing to generate realistic data.', 'active'),
('60000000-0000-0000-0000-000000001447', '50000000-0000-0000-0000-000000000052', 'intermediate', 'code_mcq', 'Which TensorFlow function creates a convolutional layer?', '["tf.keras.layers.Conv2D()", "tf.layers.conv2d()", "tf.nn.conv2d()", "tf.Conv2DLayer()"]', 'tf.keras.layers.Conv2D()', 'tf.keras.layers.Conv2D() creates a 2D convolution layer for image processing.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001448', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'What is self-attention?', '["Attention mechanism relating different positions of single sequence", "Attention between different sequences", "Fixed attention weights", "Random attention"]', 'Attention mechanism relating different positions of single sequence', 'Self-attention computes attention scores between all positions in a sequence to capture dependencies.', 'active'),
('60000000-0000-0000-0000-000000001449', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'What is the difference between CNN and fully connected networks for images?', '["CNN shares weights and detects spatial patterns", "CNN has more parameters", "Fully connected is better for images", "No difference"]', 'CNN shares weights and detects spatial patterns', 'CNNs use weight sharing and local connectivity to efficiently learn spatial hierarchies of features.', 'active'),
('60000000-0000-0000-0000-000000001450', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'What is mode collapse in GANs?', '["Generator produces limited variety of samples", "Discriminator too strong", "Training diverges", "Gradient explosion"]', 'Generator produces limited variety of samples', 'Mode collapse occurs when generator produces few types of outputs, failing to capture full data distribution.', 'active'),
('60000000-0000-0000-0000-000000001451', '50000000-0000-0000-0000-000000000052', 'expert', 'code_mcq', 'Which PyTorch class implements LSTM?', '["nn.LSTM", "nn.RNN.LSTM", "nn.RecurrentLSTM", "torch.LSTM"]', 'nn.LSTM', 'nn.LSTM implements Long Short-Term Memory networks in PyTorch.', 'active'),
('60000000-0000-0000-0000-000000001452', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'What is BERT?', '["Bidirectional Encoder Representations from Transformers", "Basic Encoder Recurrent Transformer", "Binary Encoded Representation Tree", "Bidirectional Encoder Recurrent Training"]', 'Bidirectional Encoder Representations from Transformers', 'BERT is a transformer-based model pre-trained on large text corpus using masked language modeling.', 'active');
INSERT INTO subjects (id, domain_id, name, status) 
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001453', '50000000-0000-0000-0000-000000000053', 'simple', 'mcq', 'What is image classification?', '["Predicting category/label of image", "Detecting objects in image", "Segmenting image pixels", "Generating images"]', 'Predicting category/label of image', 'Image classification assigns a single label to entire image (e.g., "cat", "dog").', 'active'),
('60000000-0000-0000-0000-000000001454', '50000000-0000-0000-0000-000000000053', 'simple', 'mcq', 'What is object detection?', '["Locating and classifying objects in image", "Classifying whole image", "Colorizing image", "Enhancing image quality"]', 'Locating and classifying objects in image', 'Object detection finds bounding boxes around objects and classifies them within an image.', 'active'),
('60000000-0000-0000-0000-000000001455', '50000000-0000-0000-0000-000000000053', 'simple', 'mcq', 'What is image segmentation?', '["Classifying each pixel in image", "Classifying whole image", "Detecting objects", "Recognizing faces"]', 'Classifying each pixel in image', 'Image segmentation assigns class label to each pixel, creating detailed understanding of image content.', 'active'),
('60000000-0000-0000-0000-000000001456', '50000000-0000-0000-0000-000000000053', 'simple', 'mcq', 'What is pooling in CNNs?', '["Downsampling feature maps", "Upsampling images", "Increasing resolution", "Adding noise"]', 'Downsampling feature maps', 'Pooling (max/average) reduces spatial dimensions, providing translation invariance and reducing parameters.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001457', '50000000-0000-0000-0000-000000000053', 'intermediate', 'mcq', 'What is transfer learning in computer vision?', '["Using pre-trained CNN for new vision tasks", "Transferring images between datasets", "Converting image formats", "Compressing images"]', 'Using pre-trained CNN for new vision tasks', 'Models pre-trained on ImageNet (ResNet, VGG) can be fine-tuned for specific vision tasks with limited data.', 'active'),
('60000000-0000-0000-0000-000000001458', '50000000-0000-0000-0000-000000000053', 'intermediate', 'mcq', 'What is YOLO?', '["Real-time object detection algorithm", "Image classification model", "Image segmentation model", "Face recognition system"]', 'Real-time object detection algorithm', 'YOLO (You Only Look Once) processes images in single pass for real-time object detection.', 'active'),
('60000000-0000-0000-0000-000000001459', '50000000-0000-0000-0000-000000000053', 'intermediate', 'mcq', 'What is U-Net?', '["Architecture for image segmentation", "Object detection model", "Image classification network", "Generative model"]', 'Architecture for image segmentation', 'U-Net has encoder-decoder structure with skip connections, widely used for biomedical image segmentation.', 'active'),
('60000000-0000-0000-0000-000000001460', '50000000-0000-0000-0000-000000000053', 'intermediate', 'code_mcq', 'Which PyTorch dataset is commonly used for image classification?', '["torchvision.datasets.CIFAR10", "torch.datasets.ImageNet", "torchvision.ImageDataset", "torch.data.CIFAR"]', 'torchvision.datasets.CIFAR10', 'torchvision.datasets.CIFAR10 provides 60,000 32x32 color images in 10 classes.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001461', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'What is non-maximum suppression?', '["Removing duplicate bounding boxes in object detection", "Removing noise from images", "Suppressing gradients", "Removing pixels"]', 'Removing duplicate bounding boxes in object detection', 'NMS keeps highest-confidence bounding boxes and removes overlapping ones with lower confidence.', 'active'),
('60000000-0000-0000-0000-000000001462', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'What is the difference between instance and semantic segmentation?', '["Instance distinguishes objects of same class", "Semantic is more accurate", "Instance is faster", "No difference"]', 'Instance distinguishes objects of same class', 'Semantic segmentation labels pixels by class; instance segmentation distinguishes individual objects of same class.', 'active'),
('60000000-0000-0000-0000-000000001463', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'What is data augmentation in computer vision?', '["Creating modified versions of images to increase dataset", "Compressing images", "Converting image formats", "Labeling images"]', 'Creating modified versions of images to increase dataset', 'Data augmentation applies transformations (rotate, flip, crop) to create variations, improving generalization.', 'active'),
('60000000-0000-0000-0000-000000001464', '50000000-0000-0000-0000-000000000053', 'expert', 'code_mcq', 'Which TensorFlow function performs image augmentation?', '["tf.keras.preprocessing.image.ImageDataGenerator", "tf.image.augment()", "tf.keras.augmentation()", "tf.data.augment_images()"]', 'tf.keras.preprocessing.image.ImageDataGenerator', 'ImageDataGenerator generates batches of tensor image data with real-time data augmentation.', 'active'),
('60000000-0000-0000-0000-000000001465', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'What is mAP in object detection?', '["Mean Average Precision", "Maximum Accuracy Percentage", "Minimum Average Precision", "Mean Accuracy Parameter"]', 'Mean Average Precision', 'mAP averages precision across recall levels and object classes, standard metric for object detection.', 'active');
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001466', '50000000-0000-0000-0000-000000000054', 'simple', 'mcq', 'What is NLP?', '["Natural Language Processing", "Neural Language Processing", "Natural Learning Process", "Neural Linguistic Programming"]', 'Natural Language Processing', 'NLP enables computers to understand, interpret, and generate human language.', 'active'),
('60000000-0000-0000-0000-000000001467', '50000000-0000-0000-0000-000000000054', 'simple', 'mcq', 'What is tokenization?', '["Splitting text into words/tokens", "Translating text", "Summarizing text", "Classifying text"]', 'Splitting text into words/tokens', 'Tokenization breaks text into smaller units (tokens) like words, subwords, or characters.', 'active'),
('60000000-0000-0000-0000-000000001468', '50000000-0000-0000-0000-000000000054', 'simple', 'mcq', 'What is word embedding?', '["Dense vector representation of words", "Word dictionary", "Word translation", "Word classification"]', 'Dense vector representation of words', 'Word embeddings map words to vectors where similar words have similar vector representations.', 'active'),
('60000000-0000-0000-0000-000000001469', '50000000-0000-0000-0000-000000000054', 'simple', 'mcq', 'What is sentiment analysis?', '["Determining emotion/opinion in text", "Translating text", "Summarizing text", "Generating text"]', 'Determining emotion/opinion in text', 'Sentiment analysis classifies text as positive, negative, or neutral based on expressed sentiment.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001470', '50000000-0000-0000-0000-000000000054', 'intermediate', 'mcq', 'What is Word2Vec?', '["Algorithm for learning word embeddings", "Word classification model", "Text generation model", "Translation algorithm"]', 'Algorithm for learning word embeddings', 'Word2Vec learns word embeddings by predicting words from context (CBOW) or context from words (Skip-gram).', 'active'),
('60000000-0000-0000-0000-000000001471', '50000000-0000-0000-0000-000000000054', 'intermediate', 'mcq', 'What is attention in NLP?', '["Focusing on relevant words in sequence", "Memory mechanism", "Word embedding", "Tokenization method"]', 'Focusing on relevant words in sequence', 'Attention allows models to focus on specific word in sequence, improving context understanding.', 'active'),
('60000000-0000-0000-0000-000000001472', '50000000-0000-0000-0000-000000000054', 'intermediate', 'mcq', 'What is sequence-to-sequence (seq2seq) model?', '["Model that transforms input sequence to output sequence", "Word classification model", "Text classification model", "Word embedding model"]', 'Model that transforms input sequence to output sequence', 'Seq2seq models, often with encoder-decoder architecture, are used for translation, summarization, etc.', 'active'),
('60000000-0000-0000-0000-000000001473', '50000000-0000-0000-0000-000000000054', 'intermediate', 'code_mcq', 'Which library is commonly used for NLP in Python?', '["NLTK", "OpenCV", "Scikit-learn", "Pandas"]', 'NLTK', 'Natural Language Toolkit (NLTK) provides tools for working with human language data.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001474', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'What is the difference between BERT and GPT?', '["BERT is bidirectional, GPT is autoregressive", "GPT is bidirectional", "BERT generates text", "No difference"]', 'BERT is bidirectional, GPT is autoregressive', 'BERT uses bidirectional context during pre-training, GPT generates text left-to-right (autoregressive).', 'active'),
('60000000-0000-0000-0000-000000001475', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'What is masked language modeling?', '["Predicting masked words in sentences", "Translating masked text", "Classifying masked documents", "Generating masked sequences"]', 'Predicting masked words in sentences', 'MLM randomly masks tokens in input and trains model to predict them, used in BERT pre-training.', 'active'),
('60000000-0000-0000-0000-000000001476', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'What is beam search?', '["Decoding algorithm for sequence generation", "Search algorithm for text", "Optimization algorithm", "Tokenization method"]', 'Decoding algorithm for sequence generation', 'Beam search keeps top-k candidates at each step during sequence generation, balancing quality and diversity.', 'active'),
('60000000-0000-0000-0000-000000001477', '50000000-0000-0000-0000-000000000054', 'expert', 'code_mcq', 'Which Hugging Face class loads pre-trained transformer models?', '["AutoModel.from_pretrained()", "Transformer.load_model()", "Model.from_huggingface()", "PretrainedModel.load()"]', 'AutoModel.from_pretrained()', 'transformers.AutoModel.from_pretrained() loads pre-trained transformer models from Hugging Face hub.', 'active'),
('60000000-0000-0000-0000-000000001478', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'What is perplexity in language modeling?', '["Measure of how well model predicts sample", "Measure of model size", "Measure of training speed", "Measure of accuracy"]', 'Measure of how well model predicts sample', 'Lower perplexity means model is more confident in its predictions; measures how surprised model is by test data.', 'active');
INSERT INTO subjects (id, domain_id, name, status) 
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001479', '50000000-0000-0000-0000-000000000055', 'simple', 'mcq', 'What is algorithmic bias?', '["Systematic errors that create unfair outcomes", "Random errors in predictions", "Training errors", "Measurement errors"]', 'Systematic errors that create unfair outcomes', 'Algorithmic bias occurs when AI systems produce systematically prejudiced results due to biased assumptions or data.', 'active'),
('60000000-0000-0000-0000-000000001480', '50000000-0000-0000-0000-000000000055', 'simple', 'mcq', 'What is fairness in AI?', '["Ensuring AI systems treat all groups equitably", "Making accurate predictions", "Training quickly", "Using less memory"]', 'Ensuring AI systems treat all groups equitably', 'Fairness means AI systems should not discriminate against individuals or groups based on sensitive attributes.', 'active'),
('60000000-0000-0000-0000-000000001481', '50000000-0000-0000-0000-000000000055', 'simple', 'mcq', 'What is transparency in AI?', '["Understanding how AI systems make decisions", "Making models faster", "Reducing model size", "Increasing accuracy"]', 'Understanding how AI systems make decisions', 'Transparency (or explainability) allows humans to understand, trust, and effectively manage AI systems.', 'active'),
('60000000-0000-0000-0000-000000001482', '50000000-0000-0000-0000-000000000055', 'simple', 'mcq', 'What is data privacy in AI?', '["Protecting personal information in datasets", "Encrypting models", "Compressing data", "Backing up data"]', 'Protecting personal information in datasets', 'Data privacy ensures that personal information in training data is protected and used ethically.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001483', '50000000-0000-0000-0000-000000000055', 'intermediate', 'mcq', 'What is the difference between disparate impact and disparate treatment?', '["Impact is outcomes, treatment is intent", "Treatment is outcomes, impact is intent", "They are the same", "Impact is legal, treatment is technical"]', 'Impact is outcomes, treatment is intent', 'Disparate treatment is intentional discrimination; disparate impact is unintentional but still harmful outcomes.', 'active'),
('60000000-0000-0000-0000-000000001484', '50000000-0000-0000-0000-000000000055', 'intermediate', 'mcq', 'What is adversarial attacks in AI?', '["Inputs designed to fool AI models", "Attacks on training data", "Model theft", "Data leakage"]', 'Inputs designed to fool AI models', 'Adversarial examples are carefully crafted inputs that cause models to make mistakes, often imperceptible to humans.', 'active'),
('60000000-0000-0000-0000-000000001485', '50000000-0000-0000-0000-000000000055', 'intermediate', 'mcq', 'What is model interpretability?', '["Understanding why model makes specific predictions", "Model accuracy", "Training efficiency", "Model size"]', 'Understanding why model makes specific predictions', 'Interpretability techniques like SHAP, LIME help explain individual predictions or overall model behavior.', 'active'),
('60000000-0000-0000-0000-000000001486', '50000000-0000-0000-0000-000000000055', 'intermediate', 'code_mcq', 'Which Python library provides fairness metrics?', '["fairlearn", "sklearn", "tensorflow", "pytorch"]', 'fairlearn', 'fairlearn is a Python package for assessing and improving fairness of machine learning models.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001487', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'What is differential privacy?', '["Mathematical framework for privacy-preserving data analysis", "Data encryption", "Model compression", "Training isolation"]', 'Mathematical framework for privacy-preserving data analysis', 'Differential privacy adds calibrated noise to query responses, providing strong privacy guarantees.', 'active'),
('60000000-0000-0000-0000-000000001488', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'What is the tradeoff between fairness and accuracy?', '["Sometimes fairer models are less accurate on majority groups", "Fair models are always more accurate", "Accuracy doesn''t affect fairness", "No tradeoff exists"]', 'Sometimes fairer models are less accurate on majority groups', 'Improving fairness for underrepresented groups may reduce overall accuracy, creating an ethical tradeoff.', 'active'),
('60000000-0000-0000-0000-000000001489', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'What is federated learning?', '["Training on decentralized data without sharing it", "Distributed training with shared data", "Centralized training", "Cloud training"]', 'Training on decentralized data without sharing it', 'Federated learning trains models across devices/servers holding local data samples without exchanging them.', 'active'),
('60000000-0000-0000-0000-000000001490', '50000000-0000-0000-0000-000000000055', 'expert', 'code_mcq', 'Which library implements SHAP for model interpretation?', '["shap", "interpret", "explain", "lime"]', 'shap', 'SHAP (SHapley Additive exPlanations) library computes Shapley values to explain model predictions.', 'active'),
('60000000-0000-0000-0000-000000001491', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'What is the EU AI Act risk classification?', '["Unacceptable, high, limited, minimal risk", "Safe, unsafe", "Approved, not approved", "Legal, illegal"]', 'Unacceptable, high, limited, minimal risk', 'The EU AI Act classifies AI systems into four risk categories with corresponding regulatory requirements.', 'active');
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001492', '50000000-0000-0000-0000-000000000056', 'simple', 'mcq', 'What is MLOps?', '["ML + DevOps for production ML systems", "Machine Learning Operations", "Model lifecycle management", "All of the above"]', 'All of the above', 'MLOps combines ML with DevOps practices to automate and streamline the ML lifecycle from development to production.', 'active'),
('60000000-0000-0000-0000-000000001493', '50000000-0000-0000-0000-000000000056', 'simple', 'mcq', 'What is model versioning?', '["Tracking different versions of models", "Compressing models", "Encrypting models", "Converting model formats"]', 'Tracking different versions of models', 'Model versioning tracks changes to models, data, and code, enabling reproducibility and rollbacks.', 'active'),
('60000000-0000-0000-0000-000000001494', '50000000-0000-0000-0000-000000000056', 'simple', 'mcq', 'What is a model registry?', '["Central repository for managing ML models", "Model training platform", "Data storage", "Feature store"]', 'Central repository for managing ML models', 'A model registry stores, versions, and manages ML models throughout their lifecycle.', 'active'),
('60000000-0000-0000-0000-000000001495', '50000000-0000-0000-0000-000000000056', 'simple', 'mcq', 'What is A/B testing for models?', '["Comparing two model versions in production", "Testing model accuracy", "Training model variants", "Debugging models"]', 'Comparing two model versions in production', 'A/B testing compares two model versions by serving them to different user segments and measuring performance.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001496', '50000000-0000-0000-0000-000000000056', 'intermediate', 'mcq', 'What is model drift?', '["Model performance degrades over time due to data changes", "Training instability", "Model compression", "Feature engineering"]', 'Model performance degrades over time due to data changes', 'Model drift occurs when the relationship between input features and target variable changes in production.', 'active'),
('60000000-0000-0000-0000-000000001497', '50000000-0000-0000-0000-000000000056', 'intermediate', 'mcq', 'What is CI/CD for ML?', '["Continuous Integration/Continuous Delivery for ML pipelines", "Model training", "Data collection", "Feature selection"]', 'Continuous Integration/Continuous Delivery for ML pipelines', 'CI/CD automates testing, building, and deployment of ML models and pipelines.', 'active'),
('60000000-0000-0000-0000-000000001498', '50000000-0000-0000-0000-000000000056', 'intermediate', 'mcq', 'What is a feature store?', '["Centralized repository for ML features", "Model storage", "Data warehouse", "Experiment tracker"]', 'Centralized repository for ML features', 'Feature stores manage, version, and serve features consistently across training and inference.', 'active'),
('60000000-0000-0000-0000-000000001499', '50000000-0000-0000-0000-000000000056', 'intermediate', 'code_mcq', 'Which tool is commonly used for ML pipeline orchestration?', '["Apache Airflow", "TensorFlow", "PyTorch", "Scikit-learn"]', 'Apache Airflow', 'Apache Airflow is a platform to programmatically author, schedule, and monitor workflows including ML pipelines.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001500', '50000000-0000-0000-0000-000000000056', 'expert', 'mcq', 'What is canary deployment for models?', '["Gradually rolling out model to small user percentage", "Full rollout to all users", "Testing on internal users", "Shadow deployment"]', 'Gradually rolling out model to small user percentage', 'Canary deployment releases model to small percentage of users, monitors performance, then gradually expands.', 'active'),
('60000000-0000-0000-0000-000000001501', '50000000-0000-0000-0000-000000000056', 'expert', 'mcq', 'What is the difference between online and batch inference?', '["Online: real-time per request, Batch: periodic on dataset", "Batch is faster", "Online uses more memory", "No difference"]', 'Online: real-time per request, Batch: periodic on dataset', 'Online inference serves predictions immediately; batch inference processes large datasets periodically.', 'active'),
('60000000-0000-0000-0000-000000001502', '50000000-0000-0000-0000-000000000056', 'expert', 'mcq', 'What is model quantization?', '["Reducing precision of model parameters to reduce size", "Increasing model accuracy", "Adding more layers", "Changing model architecture"]', 'Reducing precision of model parameters to reduce size', 'Quantization converts floating-point weights to lower precision (e.g., INT8) to reduce model size and accelerate inference.', 'active'),
('60000000-0000-0000-0000-000000001503', '50000000-0000-0000-0000-000000000056', 'expert', 'code_mcq', 'Which MLflow component tracks experiments?', '["MLflow Tracking", "MLflow Models", "MLflow Projects", "MLflow Registry"]', 'MLflow Tracking', 'MLflow Tracking logs parameters, metrics, and artifacts during model training experiments.', 'active'),
('60000000-0000-0000-0000-000000001504', '50000000-0000-0000-0000-000000000056', 'expert', 'mcq', 'What is the maximum latency for real-time inference in most applications?', '["100-200ms", "1-2 seconds", "10-20 seconds", "1 minute"]', '100-200ms', 'Most real-time applications require inference latency under 200ms for good user experience.', 'active');
